-- Private-by-default Documents, reusable templates and explicit reviews.
begin;
create table if not exists public.cb_document_categories(id text primary key,title text not null,position integer not null default 0,retired boolean not null default false);
create table if not exists public.cb_document_templates(id uuid primary key default gen_random_uuid(),created_by uuid references auth.users,official boolean not null default false,data jsonb not null,revision bigint not null default 1,updated_at timestamptz not null default now());
create table if not exists public.cb_document_template_versions(template_id uuid references public.cb_document_templates on delete cascade,revision bigint not null,data jsonb not null,at timestamptz not null default now(),primary key(template_id,revision));
create table if not exists public.cb_documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.cb_projects on delete cascade,created_by uuid not null references auth.users,template_id uuid references public.cb_document_templates,data jsonb not null,revision bigint not null default 1,content_revision bigint not null default 1,status text not null default 'Draft',deleted_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.cb_document_versions(document_id uuid references public.cb_documents on delete cascade,revision bigint not null,actor uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(document_id,revision));
create table if not exists public.cb_document_access(document_id uuid references public.cb_documents on delete cascade,user_id uuid references auth.users,permission text not null check(permission in ('View','Edit','Review')),primary key(document_id,user_id));
create table if not exists public.cb_document_comments(id uuid primary key default gen_random_uuid(),document_id uuid references public.cb_documents on delete cascade,author uuid not null references auth.users,body text not null,suggestion boolean not null default false,at timestamptz not null default now());
create table if not exists public.cb_document_reviews(id uuid primary key default gen_random_uuid(),document_id uuid references public.cb_documents on delete cascade,reviewer uuid not null references auth.users,content_revision bigint not null,decision text not null,note text not null default '',at timestamptz not null default now());
create table if not exists public.cb_document_folders(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.cb_projects on delete cascade,user_id uuid not null references auth.users,parent_id uuid references public.cb_document_folders,title text not null);
create table if not exists public.cb_document_writes(user_id uuid references auth.users,client uuid,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_document_feedback(id uuid primary key default gen_random_uuid(),template_id uuid references public.cb_document_templates,user_id uuid references auth.users,rating integer not null check(rating between 1 and 5),body text not null,at timestamptz not null default now());
do $tables$ declare t text;begin foreach t in array array['cb_document_categories','cb_document_templates','cb_document_template_versions','cb_documents','cb_document_versions','cb_document_access','cb_document_comments','cb_document_reviews','cb_document_folders','cb_document_writes','cb_document_feedback'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end;$tables$;
create index if not exists cb_documents_project on public.cb_documents(project_id,updated_at desc);
create or replace function public.cb_document_admin() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select is_admin from public.cb_profiles where user_id=auth.uid()),false)$$;
create or replace function public.cb_document_allowed(p_doc uuid,p_edit boolean default false) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.cb_documents d where d.id=p_doc and public.cb_project_access(d.project_id,'read') and (not p_edit or not exists(select 1 from public.cb_projects where id=d.project_id and archived_at is not null)) and (d.created_by=auth.uid() or exists(select 1 from public.cb_document_access a where a.document_id=d.id and a.user_id=auth.uid() and (not p_edit or a.permission='Edit'))));
$$;
create or replace function public.cb_document_file_access(p_bucket text,p_path text) returns boolean language sql stable security definer set search_path='' as $$
 select p_bucket='cb-documents' and exists(select 1 from public.cb_documents d cross join lateral jsonb_array_elements(coalesce(d.data->'files','[]')) f where d.deleted_at is null and public.cb_document_allowed(d.id) and f->>'path'=p_path);
$$;
drop policy if exists cb_document_library_file_read on storage.objects;
create policy cb_document_library_file_read on storage.objects for select to authenticated using(public.cb_document_file_access(bucket_id,name));
create or replace function public.cb_document_catalog(p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if not public.cb_project_access(p_project,'read') then raise exception 'Wedding access required' using errcode='42501';end if;
 return jsonb_build_object('title',(select title from public.cb_projects where id=p_project),'admin',public.cb_document_admin(),'premium',public.cb_has_premium(),'categories',(select coalesce(jsonb_agg(to_jsonb(c) order by position),'[]') from public.cb_document_categories c where not retired or public.cb_document_admin()),'templates',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'revision',t.revision,'official',t.official,'own',coalesce(t.created_by=auth.uid(),false),'title',t.data->>'title','category',t.data->>'category','country',t.data->>'country','tier',t.data->>'tier','featured',t.data->'featured','status',t.data->>'status','description',t.data->>'description','uses',case when public.cb_document_admin() then (select count(*) from public.cb_documents d where d.template_id=t.id) end) order by (t.data->>'featured') desc,t.data->>'title'),'[]') from public.cb_document_templates t where coalesce(t.created_by=auth.uid(),false) or t.official and (public.cb_document_admin() or t.data->>'status'='Published')),
 'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'title',d.data->>'title','category',d.data->>'category','event',d.data->>'event','tags',d.data->'tags','links',d.data->'links','folder',d.data->>'folder','favorite',d.data->'favorite','deadline',d.data->>'deadline','expiry',d.data->>'expiry','status',d.status,'revision',d.revision,'own',d.created_by=auth.uid(),'deleted_at',d.deleted_at,'updated_at',d.updated_at) order by d.updated_at desc),'[]') from public.cb_documents d where d.project_id=p_project and public.cb_document_allowed(d.id) and (d.deleted_at is null or d.created_by=auth.uid() and d.deleted_at>now()-interval '30 days')),
 'people',(select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'name',coalesce(pr.full_name,'Wedding collaborator'))),'[]') from (select owner_id id from public.cb_projects where id=p_project union select user_id from public.cb_members where project_id=p_project) u left join public.cb_profiles pr on pr.user_id=u.id where public.cb_collab_user_access(u.id,p_project,'read')),'references',(select coalesce(jsonb_agg(x),'[]') from (select 'Task' as kind,t.id,t.title,null::text as parent from public.cb_tasks t where t.project_id=p_project and public.cb_task_visible(t.id) union all select 'Vendor',v.id,v.name,null::text from public.cb_shared_vendors v where v.project_id=p_project and public.cb_shared_vendor_access(v.id) union all select 'Payment',x.id,e.title||' · '||x.paid_on::text,e.id::text from public.cb_shared_payments x join public.cb_shared_expenses e on e.id=x.expense_id where e.project_id=p_project and public.cb_project_access(p_project,'finance')) x),'folders',(select coalesce(jsonb_agg(to_jsonb(f)),'[]') from public.cb_document_folders f where f.project_id=p_project and f.user_id=auth.uid()),'events',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'date',e.details->>'date','venue',e.details->>'venue')),'[]') from public.cb_project_events e where e.project_id=p_project and public.cb_project_event_access(e.id)));
end;$$;
create or replace function public.cb_document_detail(p_doc uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d public.cb_documents;
begin
 if not public.cb_document_allowed(p_doc) then raise exception 'Document access required' using errcode='42501';end if;select * into d from public.cb_documents where id=p_doc;
 if d.deleted_at is not null and (d.created_by<>auth.uid() or d.deleted_at<=now()-interval '30 days') then raise exception 'Document is in the recovery folder';end if;
 return to_jsonb(d)||jsonb_build_object('can_edit',public.cb_document_allowed(d.id,true) and d.deleted_at is null,'own',d.created_by=auth.uid(),'can_review',exists(select 1 from public.cb_document_access where document_id=d.id and user_id=auth.uid() and permission in ('Review','Edit')),'access',case when d.created_by=auth.uid() then (select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.cb_document_access a where document_id=d.id) else '[]'::jsonb end,'comments',(select coalesce(jsonb_agg(to_jsonb(c) order by at),'[]') from public.cb_document_comments c where document_id=d.id),'reviews',(select coalesce(jsonb_agg(to_jsonb(r) order by at),'[]') from public.cb_document_reviews r where document_id=d.id),'versions',(select coalesce(jsonb_agg(jsonb_build_object('revision',v.revision,'at',v.at) order by v.revision desc),'[]') from (select * from public.cb_document_versions where document_id=d.id order by revision desc limit 30) v));
end;$$;
create or replace function public.cb_document_template(p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare t public.cb_document_templates;
begin
 select * into t from public.cb_document_templates where id=p_id;
 if t.id is null or not (coalesce(t.created_by=auth.uid(),false) or t.official and (public.cb_document_admin() or t.data->>'status'='Published')) then raise exception 'Template access required' using errcode='42501';end if;
 if t.data->>'tier'='Premium' and not (public.cb_has_premium() or public.cb_document_admin() or coalesce(t.created_by=auth.uid(),false)) then return jsonb_build_object('locked',true,'title',t.data->>'title');end if;
 return to_jsonb(t)||jsonb_build_object('versions',case when public.cb_document_admin() or coalesce(t.created_by=auth.uid(),false) then (select coalesce(jsonb_agg(jsonb_build_object('revision',revision,'data',data)),'[]') from public.cb_document_template_versions where template_id=t.id) else '[]'::jsonb end,'feedback',case when public.cb_document_admin() then (select coalesce(jsonb_agg(jsonb_build_object('rating',rating,'body',body,'at',at)),'[]') from public.cb_document_feedback where template_id=t.id) else '[]'::jsonb end);
end;$$;
create or replace function public.cb_document_action(p_project uuid,p_doc uuid,p_revision bigint,p_client uuid,p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare d public.cb_documents;old public.cb_documents;w public.cb_document_writes;payload jsonb;result jsonb;v jsonb;f jsonb;target uuid;t public.cb_document_templates;is_owner boolean;folder public.cb_document_folders;
begin
 if not coalesce(public.cb_project_access(p_project,'read'),false) then raise exception 'Wedding access required' using errcode='42501';end if;
 perform 1 from public.cb_projects where id=p_project for update;
 payload=jsonb_build_object('project',p_project,'doc',p_doc,'revision',p_revision,'action',p_action,'data',p_data);
 if p_client is null or octet_length(p_data::text)>400000 then raise exception 'Check document size and request';end if;
 select * into w from public.cb_document_writes where user_id=auth.uid() and client=p_client;
 if found then if w.payload is distinct from payload then raise exception 'Retry the original document request' using errcode='PT409';end if;return w.response;end if;
 if p_doc is null and p_action not in ('Create','Folder') then raise exception 'Choose a document';end if;
 if p_doc is not null then
  select * into d from public.cb_documents where id=p_doc and project_id=p_project for update;
  if d.id is null or not public.cb_document_allowed(d.id) then raise exception 'Document access required' using errcode='42501';end if;
  if d.revision is distinct from p_revision then raise exception 'Another person or device changed this document. Your edits are kept here; copy them before refreshing.' using errcode='PT409';end if;
  if d.deleted_at is not null and p_action not in ('Recover','Purge') then raise exception 'Recover this document before changing it';end if;
  is_owner=d.created_by=auth.uid();old=d;
 end if;
 if p_action='Folder' then
  if length(trim(coalesce(p_data->>'title',''))) not between 1 and 120 then raise exception 'Give the folder a name';end if;
  if nullif(p_data->>'parent','') is not null and not exists(select 1 from public.cb_document_folders where id=(p_data->>'parent')::uuid and user_id=auth.uid() and project_id=p_project) then raise exception 'Choose your own parent folder';end if;
  insert into public.cb_document_folders(project_id,user_id,parent_id,title) values(p_project,auth.uid(),nullif(p_data->>'parent','')::uuid,trim(p_data->>'title')) returning * into folder;result=to_jsonb(folder);
 elsif p_action in ('Create','Save') then
  if p_action='Create' then if p_doc is not null then raise exception 'Choose a new document';end if;else if not public.cb_document_allowed(d.id,true) then raise exception 'Document editing access required' using errcode='42501';end if;end if;
  if jsonb_typeof(p_data)<>'object' or length(trim(coalesce(p_data->>'title',''))) not between 1 and 200 or jsonb_typeof(p_data->'html') is distinct from 'string' or length(coalesce(p_data->>'html',''))>200000 or jsonb_typeof(p_data->'tags') is distinct from 'array' or jsonb_typeof(p_data->'files') is distinct from 'array' or jsonb_array_length(p_data->'files')>30 or jsonb_array_length(p_data->'tags')>30 then raise exception 'Check document title, tags and file limits';end if;
  if not exists(select 1 from public.cb_document_categories where id=p_data->>'category') or coalesce(p_data->>'sensitivity','') not in ('Private','Identity & legal','Journal & counseling') then raise exception 'Choose a category and privacy type';end if;
  if nullif(p_data->>'folder','') is not null and not exists(select 1 from public.cb_document_folders where id=(p_data->>'folder')::uuid and user_id=auth.uid() and project_id=p_project) then raise exception 'Choose your own document folder';end if;
  if nullif(p_data->>'event','') is not null and not exists(select 1 from public.cb_project_events where id=(p_data->>'event')::uuid and project_id=p_project and public.cb_project_event_access(id)) then raise exception 'Choose an accessible celebration';end if;
  for v in select value from jsonb_array_elements(coalesce(p_data->'links','[]')) loop
   target=(v->>'id')::uuid;
   if not (case v->>'kind' when 'Task' then exists(select 1 from public.cb_tasks where id=target and project_id=p_project and public.cb_task_visible(id)) when 'Vendor' then exists(select 1 from public.cb_shared_vendors where id=target and project_id=p_project and public.cb_shared_vendor_access(id)) when 'Payment' then exists(select 1 from public.cb_shared_payments x join public.cb_shared_expenses e on e.id=x.expense_id where x.id=target and e.project_id=p_project and public.cb_project_access(p_project,'finance')) else false end) then raise exception 'Choose an accessible linked record';end if;
  end loop;
  for v in select to_jsonb(x) from (values (p_data->>'deadline'),(p_data->>'expiry')) x(value) loop if coalesce(v->>'f1',v->>'value','')<>'' then perform coalesce(v->>'f1',v->>'value')::date;end if;end loop;
  if p_action='Save' and not is_owner and p_data->'reminder' is distinct from d.data->'reminder' then raise exception 'Only the creator manages reminder preferences';end if;
  for v in select to_jsonb(owner_key) from (select distinct split_part(item->>'path','/',1) owner_key from jsonb_array_elements(p_data->'files') item order by owner_key) owners loop perform pg_advisory_xact_lock(hashtextextended((v#>>'{}')||':files',0));end loop;
  for f in select value from jsonb_array_elements(p_data->'files') loop
   if not exists(select 1 from storage.objects where bucket_id='cb-documents' and name=f->>'path') or exists(select 1 from public.cb_file_reservations where bucket='cb-documents' and path=f->>'path' and deleting) or not (split_part(f->>'path','/',1)=auth.uid()::text or public.cb_document_file_access('cb-documents',f->>'path') or exists(select 1 from jsonb_array_elements(coalesce(d.data->'files','[]')) existing where existing->>'path'=f->>'path')) then raise exception 'Upload your own file or use an accessible document attachment';end if;
  end loop;
  if p_action='Create' then
   if nullif(p_data->>'legacyId','') is not null then select * into d from public.cb_documents where project_id=p_project and created_by=auth.uid() and data->>'legacyId'=p_data->>'legacyId';if found then result=jsonb_build_object('id',d.id,'revision',d.revision,'already_imported',true);insert into public.cb_document_writes values(auth.uid(),p_client,payload,result);return result;end if;end if;
   if nullif(p_data->>'template','') is not null then v=public.cb_document_template((p_data->>'template')::uuid);if coalesce((v->>'locked')::boolean,false) then raise exception 'A premium plan is needed for this template';end if;for f in select value from jsonb_array_elements(v->'data'->'fields') loop if coalesce((f->>'required')::boolean,false) and trim(coalesce(p_data->'personalization'->>(f->>'key'),''))='' then raise exception 'Complete the required template fields before creating the document';end if;end loop;end if;
   insert into public.cb_documents(project_id,created_by,template_id,data) values(p_project,auth.uid(),nullif(p_data->>'template','')::uuid,p_data) returning * into d;
  else update public.cb_documents set data=p_data,revision=revision+1,content_revision=content_revision+case when (data->'html',data->'files',data->'title') is distinct from (p_data->'html',p_data->'files',p_data->'title') then 1 else 0 end,status=case when (data->'html',data->'files',data->'title') is distinct from (p_data->'html',p_data->'files',p_data->'title') then 'Draft' else status end,updated_at=now() where id=d.id returning * into d;end if;
 elsif p_action='Purge' then if not is_owner or d.deleted_at is null then raise exception 'Move your own document to recovery first';end if;delete from public.cb_document_writes purge_row where purge_row.payload->>'doc'=d.id::text or purge_row.response->>'id'=d.id::text;delete from public.cb_documents where id=d.id;result=jsonb_build_object('purged',true,'id',d.id);d.id=null;
 elsif p_action='Comment' then
  if not is_owner and not exists(select 1 from public.cb_document_access where document_id=d.id and user_id=auth.uid() and permission in ('Edit','Review')) then raise exception 'Comment or review access required' using errcode='42501';end if;
  if length(trim(coalesce(p_data->>'body',''))) not between 1 and 3000 then raise exception 'Write a comment up to 3000 characters';end if;
  insert into public.cb_document_comments(document_id,author,body,suggestion) values(d.id,auth.uid(),p_data->>'body',coalesce((p_data->>'suggestion')::boolean,false));update public.cb_documents set revision=revision+1,updated_at=now() where id=d.id returning * into d;
 elsif p_action='Review' then
  if d.status<>'Under review' or not exists(select 1 from public.cb_document_access where document_id=d.id and user_id=auth.uid() and permission in ('Review','Edit')) then raise exception 'A current review invitation is required';end if;
  if p_data->>'decision' not in ('Approved','Changes requested') then raise exception 'Choose a review response';end if;
  insert into public.cb_document_reviews(document_id,reviewer,content_revision,decision,note) values(d.id,auth.uid(),d.content_revision,p_data->>'decision',left(coalesce(p_data->>'note',''),3000));
  update public.cb_documents set status=case when p_data->>'decision'='Changes requested' then 'Draft' when not exists(select 1 from public.cb_document_access a where a.document_id=d.id and a.permission in ('Review','Edit') and not exists(select 1 from public.cb_document_reviews r where r.document_id=d.id and r.content_revision=d.content_revision and r.reviewer=a.user_id and r.decision='Approved')) then 'Approved' else 'Under review' end,revision=revision+1,updated_at=now() where id=d.id returning * into d;
 elsif p_action in ('Share','Revoke','Status','Delete','Recover','Restore') then
  if not is_owner then raise exception 'Only the document creator can manage access and recovery' using errcode='42501';end if;
  if p_action='Share' then
   if p_data->>'permission' not in ('View','Edit','Review') or p_data->>'confirm' is distinct from 'true' then raise exception 'Confirm the sharing permission';end if;target=(p_data->>'user')::uuid;
   if target=auth.uid() or not public.cb_collab_user_access(target,p_project,'read') then raise exception 'Choose an accepted wedding collaborator';end if;
   insert into public.cb_document_access values(d.id,target,p_data->>'permission') on conflict(document_id,user_id) do update set permission=excluded.permission;
  elsif p_action='Revoke' then delete from public.cb_document_access where document_id=d.id and user_id=(p_data->>'user')::uuid;
  elsif p_action='Status' then
   if p_data->>'status' not in ('Draft','Under review','Signed','Archived') then raise exception 'Approvals require reviewer responses';end if;
   if p_data->>'status'='Signed' and (coalesce(p_data->>'signedDate','')='' or jsonb_array_length(d.data->'files')=0) then raise exception 'Attach a signed copy and record its signature date';end if;
   if p_data->>'status'='Under review' and not exists(select 1 from public.cb_document_access where document_id=d.id and permission in ('Review','Edit')) then raise exception 'Assign a reviewer before requesting approval';end if;
   if p_data->>'status'='Signed' then if (p_data->>'signedDate')::date>current_date or not exists(select 1 from jsonb_array_elements(d.data->'files') attached where attached.value->>'path'=p_data->>'signedFile') then raise exception 'Choose the signed attachment and a valid signature date';end if;end if;if p_data->>'status'='Under review' then d.content_revision=d.content_revision+1;end if;
   d.status=p_data->>'status';d.data=d.data||jsonb_build_object('signedDate',coalesce(p_data->>'signedDate',''),'signedFile',coalesce(p_data->>'signedFile',''));
  elsif p_action='Delete' then d.deleted_at=now();
  elsif p_action='Recover' then if d.deleted_at is null or d.deleted_at<now()-interval '30 days' then raise exception 'Recovery period has ended';end if;d.deleted_at=null;
  elsif p_action='Restore' then select snapshot->'data' into v from public.cb_document_versions where document_id=d.id and revision=(p_data->>'version')::bigint;if v is null then raise exception 'Version not found';end if;for f in select value from jsonb_array_elements(v->'files') order by value->>'path' loop perform pg_advisory_xact_lock(hashtextextended(split_part(f->>'path','/',1)||':files',0));if exists(select 1 from public.cb_file_reservations where bucket='cb-documents' and path=f->>'path' and deleting) then raise exception 'A file is being cleaned up. Restore another version or upload the original again.';end if;if not exists(select 1 from storage.objects where bucket_id='cb-documents' and name=f->>'path') then raise exception 'A file in this version is no longer available';end if;end loop;d.data=v;d.content_revision=d.content_revision+1;d.status='Draft';end if;
  update public.cb_documents set data=d.data,status=d.status,deleted_at=d.deleted_at,content_revision=d.content_revision,revision=revision+1,updated_at=now() where id=d.id returning * into d;
 else raise exception 'Unknown document action';end if;
 if d.id is not null then insert into public.cb_document_versions values(d.id,d.revision,auth.uid(),to_jsonb(d),now()) on conflict do nothing;result=jsonb_build_object('id',d.id,'revision',d.revision,'status',d.status);end if;
 insert into public.cb_document_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
create or replace function public.cb_document_template_save(p_id uuid,p_revision bigint,p_data jsonb,p_official boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare t public.cb_document_templates;f jsonb;seen text[]='{}';
begin
 if auth.uid() is null then raise exception 'Sign in first';end if;
 if p_official and not public.cb_document_admin() then raise exception 'Template administrator required' using errcode='42501';end if;
 if length(trim(coalesce(p_data->>'title',''))) not between 1 and 200 or octet_length(p_data::text)>250000 or coalesce(p_data->>'tier','') not in ('Free','Premium') or coalesce(p_data->>'status','') not in ('Draft','Published','Retired') or jsonb_typeof(p_data->'fields') is distinct from 'array' or not exists(select 1 from public.cb_document_categories where id=p_data->>'category') then raise exception 'Check template details';end if;
 if jsonb_array_length(p_data->'fields')>30 then raise exception 'Keep up to thirty personalization fields';end if;
 for f in select value from jsonb_array_elements(p_data->'fields') loop
  if coalesce(f->>'key','')!~'^[a-zA-Z][a-zA-Z0-9_-]{0,40}$' or length(trim(coalesce(f->>'label',''))) not between 1 and 120 or jsonb_typeof(f->'required') is distinct from 'boolean' or f->>'key'=any(seen) then raise exception 'Check unique field keys, labels and required settings';end if;seen=array_append(seen,f->>'key');
 end loop;
 if p_id is null or p_revision=0 and not exists(select 1 from public.cb_document_templates where id=p_id) then insert into public.cb_document_templates(id,created_by,official,data) values(coalesce(p_id,gen_random_uuid()),auth.uid(),p_official,p_data) returning * into t;
 else select * into t from public.cb_document_templates where id=p_id for update;
 if t.id is null or not (coalesce(t.created_by=auth.uid(),false) and not t.official or t.official and public.cb_document_admin()) then raise exception 'Template editing access required' using errcode='42501';end if;
 if p_revision=0 and t.revision=1 and coalesce(t.created_by=auth.uid(),false) and t.data=p_data and t.official=p_official then return to_jsonb(t);end if;
 if t.revision<>p_revision then raise exception 'This template changed. Refresh it first.' using errcode='PT409';end if;
 update public.cb_document_templates set data=p_data,official=p_official,revision=revision+1,updated_at=now() where id=t.id returning * into t;end if;
 insert into public.cb_document_template_versions values(t.id,t.revision,t.data,now());return to_jsonb(t);
end;$$;
create or replace function public.cb_document_category_save(p_id text,p_title text,p_position integer,p_retired boolean) returns void language plpgsql security definer set search_path='' as $$begin if not public.cb_document_admin() then raise exception 'Template administrator required' using errcode='42501';end if;if p_id!~'^[a-z-]{1,60}$' or length(trim(p_title)) not between 1 and 100 then raise exception 'Check category name';end if;insert into public.cb_document_categories values(p_id,p_title,p_position,p_retired) on conflict(id) do update set title=excluded.title,position=excluded.position,retired=excluded.retired;end;$$;
create or replace function public.cb_document_feedback(p_template uuid,p_rating integer,p_body text) returns void language plpgsql security definer set search_path='' as $$begin perform public.cb_document_template(p_template);if length(p_body)>3000 then raise exception 'Keep feedback under 3000 characters';end if;insert into public.cb_document_feedback(template_id,user_id,rating,body) values(p_template,auth.uid(),p_rating,p_body);end;$$;
-- Attachments remain protected while referenced by a live document or recoverable version.
do $wrap$ begin if to_regprocedure('public.cb_file_referenced_before_documents(text,text)') is null then alter function public.cb_file_referenced(text,text) rename to cb_file_referenced_before_documents;end if;end;$wrap$;
create or replace function public.cb_file_referenced(p_bucket text,p_path text) returns boolean language sql security definer set search_path='' as $$select public.cb_file_referenced_before_documents(p_bucket,p_path) or p_bucket='cb-documents' and (exists(select 1 from public.cb_documents d cross join lateral jsonb_array_elements(coalesce(d.data->'files','[]')) f where (d.deleted_at is null or d.deleted_at>now()-interval '30 days') and f->>'path'=p_path) or exists(select 1 from public.cb_document_versions v cross join lateral jsonb_array_elements(coalesce(v.snapshot->'data'->'files','[]')) f where v.at>now()-interval '30 days' and f->>'path'=p_path))$$;
revoke all on function public.cb_document_admin(),public.cb_document_allowed(uuid,boolean),public.cb_document_file_access(text,text),public.cb_document_catalog(uuid),public.cb_document_detail(uuid),public.cb_document_template(uuid),public.cb_document_action(uuid,uuid,bigint,uuid,text,jsonb),public.cb_document_template_save(uuid,bigint,jsonb,boolean),public.cb_document_category_save(text,text,integer,boolean),public.cb_document_feedback(uuid,integer,text),public.cb_file_referenced(text,text),public.cb_file_referenced_before_documents(text,text) from public,anon,authenticated;
grant execute on function public.cb_document_file_access(text,text),public.cb_document_catalog(uuid),public.cb_document_detail(uuid),public.cb_document_template(uuid),public.cb_document_action(uuid,uuid,bigint,uuid,text,jsonb),public.cb_document_template_save(uuid,bigint,jsonb,boolean),public.cb_document_category_save(text,text,integer,boolean),public.cb_document_feedback(uuid,integer,text),public.cb_file_referenced(text,text) to authenticated;
do $refresh$ declare s text;b text;begin foreach s in array array['public.cb_claim_unused_files()','public.cb_file_delete_allowed(text,text)'] loop if to_regprocedure(s) is not null then b=pg_get_functiondef(to_regprocedure(s));execute b;end if;end loop;end;$refresh$;
notify pgrst,'reload schema';commit;


